sys_script_fix.script:
(function() {

    var tableName = "change_request";  

    var fieldName = "type";            // "Change Type" field

    var newValue = "u_my_change";      // internal value (must be unique)

    var newLabel = "My Change Type";   // label shown on the form

    var order = 400;                   // sequence order

    // Check if choice already exists

    var gr = new GlideRecord("sys_choice");

    gr.addQuery("name", tableName);

    gr.addQuery("element", fieldName);

    gr.addQuery("value", newValue);

    gr.query();

    if (gr.next()) {

        gs.print("Change Type already exists: " + newValue);

        return;

    }

    // Create new choice

    var choice = new GlideRecord("sys_choice");

    choice.initialize();

    choice.name = tableName;

    choice.element = fieldName;

    choice.value = newValue;

    choice.label = newLabel;

    choice.sequence = order;

    choice.language = "en";

    choice.insert();

    gs.print("New Change Type created: " + newLabel + " (" + newValue + ")");

})();
